function levelOrder(root) {
  if (!root) return;
  const queue = [root];
  while (queue.length > 0) {
    const node = queue.shift();
    console.log(node.value);
    if (node.left) queue.push(node.left);
    if (node.right) queue.push(node.right);
  }
}
```

```js
function getHeight(root) {
  if (!root) return -1;
  return 1 + Math.max(getHeight(root.left), getHeight(root.right));
}

function getDepth(node, target, depth = 0) {
  if (!node) return -1;
  if (node.value === target) return depth;
  return Math.max(
    getDepth(node.left, target, depth + 1),
    getDepth(node.right, target, depth + 1)
  );
}
```

```js
function invertTree(root) {
  if (!root) return null;
  [root.left, root.right] = [invertTree(root.right), invertTree(root.left)];
  return root;
}
```

```js
function countNodes(root) {
  if (!root) return 0;
  return 1 + countNodes(root.left) + countNodes(root.right);
}

function countLeaves(root) {
  if (!root) return 0;
  if (!root.left && !root.right) return 1;
  return countLeaves(root.left) + countLeaves(root.right);
}

function countInternal(root) {
  if (!root || (!root.left && !root.right)) return 0;
  return 1 + countInternal(root.left) + countInternal(root.right);
}
```

```js
function serialize(root) {
  if (!root) return 'null';
  return `${root.value},${serialize(root.left)},${serialize(root.right)}`;
}

let index = 0;
function deserialize(data) {
  const values = data.split(',');
  function helper() {
    if (values[index] === 'null') {
      index++;
      return null;
    }
    const node = new TreeNode(Number(values[index++]));
    node.left = helper();
    node.right = helper();
    return node;
  }
  return helper();
}
```

```js
function isBalanced(root) {
  function check(node) {
    if (!node) return [true, -1];

    const [leftBalanced, leftHeight] = check(node.left);
    const [rightBalanced, rightHeight] = check(node.right);

    const balanced =
      leftBalanced && rightBalanced && Math.abs(leftHeight - rightHeight) <= 1;

    return [balanced, 1 + Math.max(leftHeight, rightHeight)];
  }
  return check(root)[0];
}
```

```js
function hasPathSum(root, sum) {
  if (!root) return false;
  if (!root.left && !root.right && root.value === sum) return true;
  return (
    hasPathSum(root.left, sum - root.value) ||
    hasPathSum(root.right, sum - root.value)
  );
}
